classDiagram
    class AggregateRoot {
        +Role: Root entity of an aggregate
        +KeyResponsibility: Checks consistency of changes in the aggregate
    }
    class Repository {
        +Role: Object for retrieving domain objects
        +KeyResponsibility: Methods for retrieving domain objects
    }
    class Factory {
        +Role: Object for creating domain objects
        +KeyResponsibility: Methods for directly creating domain objects
    }
    Repository --> AggregateRoot : Retrieves domain objects from a data store
    Factory --> AggregateRoot : Directly creates domain objects

flowchart TD
    subG[Generator Strategy: μ_G]
    subD[Discriminator Strategy: μ_D]
    ref[Reference Distribution: μ_ref]
    noise[Latent Noise: z ~ μ_Z]

    noise -->|Pushforward G⁻¹| subG
    subG -->|Synthetic Samples x ~ μ_G| Eval{Objective Function L}
    ref -->|Real Samples x ~ μ_ref| Eval
    subD -->|Probability y ~ μ_D(x)| Eval

    Eval -->|Minimize L| subG
    Eval -->|Maximize L| subD

    subG -.->|Aim: μ_G ≈ μ_ref| ref
    subD -.->|Aim: D(x)=1 for ref, 0 for gen| subG

    classDef strategy fill:#f9f,stroke:#333,stroke-width:2px;
    classDef data fill:#bbf,stroke:#333,stroke-width:2px;
    classDef process fill:#bfb,stroke:#333,stroke-width:2px;

    class subG,subD strategy;
    class ref,noise data;
    class Eval process;

classDiagram
    class MVCCRecord {
        +u32 insert_transaction_id
        +u32 delete_transaction_id
        +u16 data_length
        +Vec data
    }
    MVCCRecord --> VersioningWorkflow : uses
    class VersioningWorkflow {
        +insert_transaction_id : Marks version creation
        +delete_transaction_id : Marks version obsolescence
    }

classDiagram
    class MutexTypes {
        <<taxonomy>>
        +String classification_basis
    }
    class BlockingBehavior {
        +String branch_name
    }
    class BlockingLocks {
        +String description: "thread waits until lock available"
        +String design_note: "most common design"
    }
    class Spinlocks {
        +String behavior: "thread spins waiting"
        +String efficiency: "efficient for short waits"
        +String benefit: "avoids OS rescheduling overhead"
    }
    class GranularityLevels {
        +String branch_name
        +String hierarchy: "coarse to fine"
    }
    class CoarseGranularity {
        +String type: "Table locks"
        +String best_for: "single user"
        +String scope: "small number of locks protecting large data segments"
    }
    class MediumGranularity {
        +String types: "Data page locks, Record locks"
    }
    class FineGranularity {
        +String types: "Field locks, Part of field"
        +String best_for: "multiple users"
        +String benefit: "reduces lock contention"
        +String drawback: "increases overhead"
    }
    class AccessModes {
        +List~String~ modes
    }
    class Exclusive {
        +String mode_type
    }
    class Shared {
        +String mode_type: "for reading"
    }
    class IntendToExclude {
        +String mode_type: "Intend-to-exclude"
    }
    class IntendToUpgrade {
        +String mode_type: "Intend-to-upgrade"
    }
    class BinarySemaphore {
        +String description: "simplest lock type"
        +String access: "exclusive access"
    }
    class LockEnforcement {
        <<category>>
    }
    class AdvisoryLocks {
        +String type: "cooperative"
    }
    class MandatoryLocks {
        +String behavior: "force exception on unauthorized access"
    }
    class TradeoffAnalysis {
        +String coarse_tradeoff: "less overhead but more contention"
        +String fine_tradeoff: "more overhead but less contention"
    }

    MutexTypes --> BlockingBehavior : 1) Branch
    MutexTypes --> GranularityLevels : 2) Branch
    BlockingBehavior --> BlockingLocks
    BlockingBehavior --> Spinlocks
    GranularityLevels --> CoarseGranularity
    GranularityLevels --> MediumGranularity
    GranularityLevels --> FineGranularity
    BlockingLocks --> AccessModes : includes
    AccessModes --> Exclusive
    AccessModes --> Shared
    AccessModes --> IntendToExclude
    AccessModes --> IntendToUpgrade
    BlockingLocks ..> BinarySemaphore : simplest form
    LockEnforcement --> AdvisoryLocks
    LockEnforcement --> MandatoryLocks
    CoarseGranularity ..> TradeoffAnalysis : exhibits
    FineGranularity ..> TradeoffAnalysis : exhibits
